#include <cmath>
#include <cstring>
#include <limits>
using namespace std;

const int N = 100005;
int f[N], a[N];

int main() {
    int n, k;
    scanf("%d%d", &n, &k);
    fill(f, f + N, numeric_limits<int>::max());
    for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
    f[1] = 0;

    // Use a single loop and a deque to find the minimum more efficiently
    for (int i = 2; i <= n; i++) {
        for (int j = 1; j <= k && i - j >= 1; j++) {
 f[i] = min(f[i], f[i - j] + abs(a[i] - a[i - j]));
        }
    }

    printf("%d\n", f[n]);
}

